mapper.select:
SELECT b.*, s.saname, d.dname AS dept, leader.saname AS leader_name FROM board b LEFT JOIN sawon s ON b.sabun = s.sabun LEFT JOIN dept d ON s.deptno = d.deptno LEFT JOIN sawonleader sl ON d.deptno = sl.deptno LEFT JOIN sawon leader ON sl.sabun = leader.sabun
AND b.title LIKE CONCAT('%', #{keyword}, '%')
ORDER BY b.idx DESC LIMIT #{offset}, #{limit}

mapper.update:
UPDATE board 
SET views = views + 1 
WHERE idx = #{idx}

UPDATE board 
SET title = #{title}, content = #{content}, updated = NOW()
WHERE idx = #{idx}
